/**
 * GLB geometry source of an equipment bundle (types only; the loader lives in src/scene/glbParts.ts).
 * The manifest is generated by scripts/blender/build_equipment.py and checked by scripts/assets/validate-glb.mjs.
 */
export interface GlbManifestNode {
  node: string;
  parent: string | null;
  assetId: string;
  partKey: string;
  materialRef: string;
  cutaway: "keep" | "hide-in-sector";
  cover: boolean;
  lod: "" | "fine";
  jointId: string;
  pickable: boolean;
  castShadow: boolean;
  isGlass: boolean;
  triangles: number;
  boundsInstance: { min: [number, number, number]; max: [number, number, number] };
}

export interface GlbManifest {
  templateId: string;
  runtimeFile: string;
  nodes: GlbManifestNode[];
}

/** Bundle field: where the tool's GLB lives and whether the tool may run without it. */
export interface GlbSourceSpec {
  url: string;
  manifest: GlbManifest;
  /** Required for scenarios: a failed load blocks the clock (Preview blocked) instead of showing a partial tool. */
  required: boolean;
}

